cat << 'EOF' > app/page.tsx
import { unstable_cache, revalidateTag } from 'next/cache';
import { getAllProducts } from '@/lib/db';

const getCachedProducts = unstable_cache(
  async () => getAllProducts(),
  ['products-catalog'],
  { tags: ['products'] }
);

export default async function AdminCatalogPage() {
  const products = await getCachedProducts();

  async function syncCatalog() {
    'use server';
    // Mark the "products" tag as stale so the next request gets a stale-while-revalidate
    // response. This ensures the admin UI is never blocked waiting for the potentially
    // slow recomputation of thousands of SKUs, achieving eventual consistency.
    revalidateTag('products', 'max');
  }

  return (
    <main style={{ padding: '2rem', fontFamily: 'sans-serif' }}>
      <h1>Admin Product Catalog</h1>

      <div style={{ marginBottom: '2rem', padding: '1rem', border: '1px solid #ddd', borderRadius: '4px' }}>
        <h2>Sync ERP/PIM Data</h2>
        <p style={{ color: '#555', marginBottom: '1rem' }}>
          Triggering a sync will refresh the catalog data in the background. 
          The catalog views will eventually reflect the latest data without blocking the UI.
        </p>
        <form action={syncCatalog}>
          <button 
            type="submit" 
            style={{ padding: '0.5rem 1rem', background: '#0070f3', color: '#fff', border: 'none', borderRadius: '4px', cursor: 'pointer' }}
          >
            Sync latest catalog
          </button>
        </form>
      </div>

      <table style={{ width: '100%', borderCollapse: 'collapse' }}>
        <thead>
          <tr style={{ background: '#f5f5f5', textAlign: 'left' }}>
            <th style={{ padding: '0.5rem', borderBottom: '2px solid #ddd' }}>ID</th>
            <th style={{ padding: '0.5rem', borderBottom: '2px solid #ddd' }}>Name</th>
            <th style={{ padding: '0.5rem', borderBottom: '2px solid #ddd' }}>Price</th>
          </tr>
        </thead>
        <tbody>
          {products.map((product: any) => (
            <tr key={product.id} style={{ borderBottom: '1px solid #ddd' }}>
              <td style={{ padding: '0.5rem' }}>{product.id}</td>
              <td style={{ padding: '0.5rem' }}>{product.name}</td>
              <td style={{ padding: '0.5rem' }}>${product.price.toFixed(2)}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </main>
  );
}
